// generatedId matches the ids generated by the request id middlewares.
var generatedId = regexp.MustCompile(`^[0-9a-f]{32}$`)

// requestIdKey is a context key other than the one of the request ids.
type requestIdKey struct{}

// createRequestId returns the request id middleware "main" of the fields,
// created with the request id bundle and the values.
func createRequestId(t *testing.T, fields container.Bag, values map[string]any) (flam.IRestMiddleware, error) {
	t.Helper()
	return create(t, requestid.NewBundle(), requestid.Driver, fields, values, deps{})
}

// serveRequestId serves a GET of "/items/1" with the headers through the
// middleware, returning the recorded response, and the id held by the
// context of the request given to the handler, along with whether it
// holds one.
func serveRequestId(m flam.IRestMiddleware, header http.Header) (*httptest.ResponseRecorder, string, bool) {
	req := httptest.NewRequest(http.MethodGet, "/items/1", nil)
	req.Header = header
	rec := httptest.NewRecorder()
	var id string
	var ok bool
	m.Wrap(logEndpoint(0), http.HandlerFunc(func(_ http.ResponseWriter, req *http.Request) {
		id, ok = rest.RequestIdOf(req.Context())
	})).ServeHTTP(rec, req)
	return rec, id, ok
}

func Test_RequestIdOf(t *testing.T) {
	t.Run("should read the id stored in the context", func(t *testing.T) {
		for name, id := range map[string]string{"id": "abc", "empty": ""} {
			got, ok := rest.RequestIdOf(rest.WithRequestId(context.Background(), id))
			testutil.Equal(t, name+" id", got, id)
			testutil.Equal(t, name+" ok", ok, true)
		}
	})

	t.Run("should store the id in a background context in place of a nil one", func(t *testing.T) {
		var nilCtx context.Context
		ctx := rest.WithRequestId(nilCtx, "abc")
		got, ok := rest.RequestIdOf(ctx)
		testutil.Equal(t, "id", got, "abc")
		testutil.Equal(t, "ok", ok, true)
		testutil.Equal(t, "err", ctx.Err(), nil)
	})

	t.Run("should report a context without id", func(t *testing.T) {
		var nilCtx context.Context
		for name, ctx := range map[string]context.Context{
			"nil":       nilCtx,
			"no value":  context.Background(),
			"other key": context.WithValue(context.Background(), requestIdKey{}, "x"),
		} {
			got, ok := rest.RequestIdOf(ctx)
			testutil.Equal(t, name+" id", got, "")
			testutil.Equal(t, name+" ok", ok, false)
		}
	})
}

func Test_RequestId_Bundle(t *testing.T) {
	t.Run("should configure the middleware and the defaults of its fields", func(t *testing.T) {
		b := requestid.NewBundle()
		testutil.Equal(t, "Id()", b.Id(), "flam.rest.middlewares.requestid")

		bag := container.Bag{}
		testutil.NoError(t, b.(flam.IConfigurableBundle).Config(bag))
		for path, want := range map[string]any{
			rest.MiddlewareConfigPath + "." + requestid.Id: container.Bag{factory.ConfigFieldDriver: requestid.Driver},
			requestid.DefaultHeaderConfigPath:              "X-Request-Id",
		} {
			testutil.Equal(t, path, bag.Get(path), want)
		}
		for got, want := range map[string]string{
			requestid.Id:                      "requestid",
			requestid.Driver:                  "flam.rest.middlewares.driver.requestid",
			requestid.ConfigFieldHeader:       "header",
			requestid.DefaultHeaderConfigPath: "flam.rest.defaults.middlewares.requestid.header",
		} {
			testutil.Equal(t, "const", got, want)
		}
		testutil.Equal(t, "MaxLength", requestid.MaxLength, 128)
		if err := b.(flam.IConfigurableBundle).Config(container.Bag{"flam": "scalar"}); err == nil {
			t.Fatal("Config() did not fail")
		}
	})

	t.Run("should register the creator", func(t *testing.T) {
		app := testutil.NewApp()
		testutil.NoError(t, app.RegisterBundle(requestid.NewBundle()))
		testutil.Equal(t, "calls", app.Calls(), []string{"bundle:flam.rest.middlewares.requestid", "provider/1"})
	})
}

func Test_RequestId(t *testing.T) {
	t.Run("should keep a valid id of the request", func(t *testing.T) {
		m, err := createRequestId(t, container.Bag{}, nil)
		testutil.NoError(t, err)
		testutil.Equal(t, "Id()", m.Id(), "main")

		for _, id := range []string{
			"a",
			"abc-DEF_012.3:4+5/6=",
			strings.Repeat("x", requestid.MaxLength),
		} {
			rec, got, ok := serveRequestId(m, http.Header{"X-Request-Id": {id}})
			testutil.Equal(t, "context id", got, id)
			testutil.Equal(t, "ok", ok, true)
			testutil.Equal(t, "response id", rec.Header().Values("X-Request-Id"), []string{id})
		}
	})

	t.Run("should generate the id of a request without a valid one", func(t *testing.T) {
		m, err := createRequestId(t, container.Bag{}, nil)
		testutil.NoError(t, err)

		seen := map[string]bool{}
		for name, header := range map[string]http.Header{
			"missing":       {},
			"empty":         {"X-Request-Id": {""}},
			"too long":      {"X-Request-Id": {strings.Repeat("x", requestid.MaxLength+1)}},
			"space":         {"X-Request-Id": {"a b"}},
			"new line":      {"X-Request-Id": {"a\nlevel=error"}},
			"quote":         {"X-Request-Id": {`a"b`}},
			"non ascii":     {"X-Request-Id": {"é"}},
			"control":       {"X-Request-Id": {"a\x00"}},
			"bracket":       {"X-Request-Id": {"<script>"}},
			"other header":  {"X-Correlation-Id": {"abc"}},
			"after the max": {"X-Request-Id": {strings.Repeat("y", requestid.MaxLength) + "!"}},
		} {
			rec, got, ok := serveRequestId(m, header)
			testutil.Equal(t, name+" ok", ok, true)
			testutil.Equal(t, name+" generated", generatedId.MatchString(got), true)
			testutil.Equal(t, name+" response id", rec.Header().Values("X-Request-Id"), []string{got})
			testutil.Equal(t, name+" unique", seen[got], false)
			seen[got] = true
		}
	})

	t.Run("should let the handler change the id of the response", func(t *testing.T) {
		m, err := createRequestId(t, container.Bag{}, nil)
		testutil.NoError(t, err)

		rec := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, "/items/1", nil)
		req.Header.Set("X-Request-Id", "abc")
		m.Wrap(logEndpoint(0), http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			testutil.Equal(t, "set", w.Header().Get("X-Request-Id"), "abc")
			w.Header().Set("X-Request-Id", "def")
		})).ServeHTTP(rec, req)
		testutil.Equal(t, "response id", rec.Header().Get("X-Request-Id"), "def")
		testutil.Equal(t, "request header", req.Header.Get("X-Request-Id"), "abc")
	})

	t.Run("should take the field, then its default", func(t *testing.T) {
		m, err := createRequestId(t, container.Bag{requestid.ConfigFieldHeader: "x-correlation-id"},
			map[string]any{requestid.DefaultHeaderConfigPath: "X-Trace-Id"})
		testutil.NoError(t, err)
		rec, got, _ := serveRequestId(m, http.Header{"X-Correlation-Id": {"abc"}, "X-Request-Id": {"def"}})
		testutil.Equal(t, "field id", got, "abc")
		testutil.Equal(t, "field response", rec.Header(), http.Header{"X-Correlation-Id": {"abc"}})

		m, err = createRequestId(t, container.Bag{}, map[string]any{requestid.DefaultHeaderConfigPath: "X-Trace-Id"})
		testutil.NoError(t, err)
		rec, got, _ = serveRequestId(m, http.Header{"X-Trace-Id": {"ghi"}, "X-Request-Id": {"def"}})
		testutil.Equal(t, "default id", got, "ghi")
		testutil.Equal(t, "default response", rec.Header(), http.Header{"X-Trace-Id": {"ghi"}})
	})

	t.Run("should use the built-in default when the default is missing", func(t *testing.T) {
		m, err := create(t, bare{requestid.NewBundle()}, requestid.Driver, container.Bag{}, nil, deps{})
		testutil.NoError(t, err)
		rec, got, _ := serveRequestId(m, http.Header{"X-Request-Id": {"abc"}})
		testutil.Equal(t, "id", got, "abc")
		testutil.Equal(t, "response", rec.Header(), http.Header{"X-Request-Id": {"abc"}})
	})

	t.Run("should fail with an invalid field or default", func(t *testing.T) {
		for _, value := range []any{"", 1, nil, []any{"X-Request-Id"}} {
			_, err := createRequestId(t, container.Bag{requestid.ConfigFieldHeader: value}, nil)
			testutil.Error(t, errors.Unwrap(err), requestid.ErrInvalidField,
				"unable to create request id rest middleware: invalid request id rest middleware field",
				map[string]any{requestid.ErrorFieldID: "main", requestid.ErrorFieldField: requestid.ConfigFieldHeader})
		}
		_, err := createRequestId(t, container.Bag{}, map[string]any{requestid.DefaultHeaderConfigPath: 42})
		testutil.Error(t, errors.Unwrap(err), requestid.ErrInvalidField,
			"unable to create request id rest middleware: invalid request id rest middleware field",
			map[string]any{requestid.ErrorFieldID: "main", requestid.ErrorFieldField: requestid.ConfigFieldHeader})
	})

	t.Run("should leave the configurations of other drivers", func(t *testing.T) {
		_, err := createRequestId(t, container.Bag{factory.ConfigFieldDriver: "other"}, nil)
		if !errors.Is(err, factory.ErrNoCreator) {
			t.Fatalf("Get() = %v, want factory.ErrNoCreator", err)
		}
	})

	t.Run("should give the id to the log middleware listed after it", func(t *testing.T) {
		id, err := createRequestId(t, container.Bag{}, nil)
		testutil.NoError(t, err)
		l, logger, _ := newLog(t, container.Bag{})

		rec, panicked := serve(t, "/items/1", func(http.ResponseWriter, *http.Request) {}, id, l)
		testutil.Equal(t, "panicked", panicked, nil)
		generated := rec.Header().Get("X-Request-Id")
		testutil.Equal(t, "generated", generatedId.MatchString(generated), true)
		got := logger.all()
		testutil.Equal(t, "count", len(got), 2)
		for _, e := range got {
			testutil.Equal(t, "logged id", e.ctx.Get(log.ContextFieldRequest+"."+log.ContextFieldRequestId), any(generated))
		}

		logger = &entries{}
		l, err = createLog(t, container.Bag{}, nil, logger, testutil.NewClock(epoch))
		testutil.NoError(t, err)
		_, _ = serve(t, "/items/1", func(http.ResponseWriter, *http.Request) {}, l, id)
		got = logger.all()
		testutil.Equal(t, "outer count", len(got), 2)
		testutil.Equal(t, "outer logged id", got[0].ctx.Has(log.ContextFieldRequest+"."+log.ContextFieldRequestId), false)
	})
}
